window.WWM_FAQ = {"version":1,"course_id":"VA-1","entries":[{"id":"faq.mark-complete","section_id":"va-1.future.s9","question_en":"How do I finish this lesson?","question_am":"ይህን ትምህርት እንዴት ልጨርስ?","answer_en":"Scroll to the end of the lesson and press Mark as complete. Your progress is saved.","answer_am":null,"keywords_en":["finish","complete","done","mark","end","progress","save","lesson","completed"],"keywords_am":["ልጨርስ","ጨርስ","ተጠናቋል"],"action_id":"mark_complete"},{"id":"faq.sidebar","section_id":null,"question_en":"Where is the course outline or menu?","question_am":null,"answer_en":"Press the Menu button at the top left. It opens the course outline with every section of this lesson.","answer_am":null,"keywords_en":["menu","outline","sidebar","hamburger","sections","contents","navigation"],"keywords_am":[],"action_id":"toggle_sidebar"},{"id":"faq.courses","section_id":null,"question_en":"How do I switch to another course?","question_am":null,"answer_en":"Press My courses at the top of the page. A list of your courses opens. Choose one.","answer_am":null,"keywords_en":["courses","course","switch","change","another","other","list","dropdown"],"keywords_am":[],"action_id":"open_courses_menu"},{"id":"faq.programme","section_id":null,"question_en":"Where can I see my programme details?","question_am":null,"answer_en":"On the dashboard, press Programme details. A window opens with your programme name, dates and support contact.","answer_am":null,"keywords_en":["programme","program","details","dates","cohort","start"],"keywords_am":[],"action_id":"open_programme_modal"},{"id":"faq.score","section_id":null,"question_en":"Where do I see my score?","question_am":null,"answer_en":"On the dashboard, press Score details. A window shows your score for each week.","answer_am":null,"keywords_en":["score","marks","grade","result","results","points","progress"],"keywords_am":[],"action_id":"open_score_details"},{"id":"faq.week","section_id":null,"question_en":"How do I go to another week?","question_am":null,"answer_en":"On the dashboard, use the week strip near the top. Press a week number to see that week's work.","answer_am":null,"keywords_en":["week","weeks","previous","strip","schedule"],"keywords_am":[],"action_id":"switch_week"},{"id":"faq.next-concept","section_id":null,"question_en":"How do I go to the next lesson?","question_am":null,"answer_en":"Use the curriculum bar at the bottom of the lesson page. Press Next concept.","answer_am":null,"keywords_en":["next","lesson","concept","curriculum","bar","continue","forward"],"keywords_am":[],"action_id":"open_curriculum_nav"},{"id":"faq.person","section_id":null,"question_en":"Can I talk to a person?","question_am":null,"answer_en":"Yes. Press Talk to a person at the top of this panel. You see what will be sent before anything is sent.","answer_am":null,"keywords_en":["person","human","staff","helper","teacher","someone","support","call","talk"],"keywords_am":["ሰው"],"action_id":"open_help"},{"id":"faq.what-is-va","section_id":"va-1.future.s2","question_en":"What does a virtual assistant do?","question_am":null,"answer_en":"A virtual assistant supports a business from a distance. Common tasks are managing email, scheduling meetings, entering data, answering customer messages, booking travel and preparing simple reports.","answer_am":null,"keywords_en":["virtual","assistant","va","tasks","job","work","email","schedule","meaning","definition"],"keywords_am":[],"action_id":null},{"id":"faq.demand","section_id":"va-1.future.s3","question_en":"Why is demand for virtual assistants growing?","question_am":null,"answer_en":"More companies hire remote workers. Small businesses can hire a VA for a few hours a week, and remote hiring lets work continue across time zones.","answer_am":null,"keywords_en":["demand","growing","growth","why","remote","companies","hire","industry","future"],"keywords_am":[],"action_id":null},{"id":"faq.tools","section_id":"va-1.future.s4","question_en":"Which tools does a virtual assistant use?","question_am":null,"answer_en":"Email, a shared calendar, a spreadsheet program, a document editor, a video call app and a task board. Many clients also use a password manager.","answer_am":null,"keywords_en":["tools","software","apps","calendar","spreadsheet","video","password","task","board"],"keywords_am":[],"action_id":null},{"id":"faq.skills","section_id":"va-1.future.s5","question_en":"Which skills do employers ask for?","question_am":null,"answer_en":"Clear written communication, good time management, attention to detail and reliability. Working without close supervision is important too.","answer_am":null,"keywords_en":["skills","employers","communication","time","management","detail","reliable","reliability","soft"],"keywords_am":[],"action_id":null},{"id":"faq.ai","section_id":"va-1.future.s6","question_en":"Will AI replace virtual assistants?","question_am":null,"answer_en":"The lesson says AI changes VA work but does not remove it. Clients still need a person who checks the work and makes judgement calls.","answer_am":null,"keywords_en":["ai","automation","replace","robots","chatgpt","artificial","intelligence","future"],"keywords_am":[],"action_id":null},{"id":"faq.portfolio","section_id":"va-1.future.s7","question_en":"What should be in my portfolio?","question_am":null,"answer_en":"Three strong examples, such as a sample schedule, a cleaned spreadsheet, a well written email or a short report. Remove private client details first.","answer_am":null,"keywords_en":["portfolio","examples","samples","show","work","first","client"],"keywords_am":[],"action_id":null}],"sections":{"va-1.future.s1":{"title_en":"Introduction","title_am":null,"anchor":"wwm-s1","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"This lesson explains what the virtual assistant industry is, why it is growing, and which skills will matter most in the next five years. A virtual assistant, or VA, is a person who supports a business or a busy professional from a distance, usually over the internet. By the end of the lesson you should be able to describe the main types of VA work and name three skills you want to build.","keywords_en":["introduction","lesson","virtual","assistant","skills","explains","industry","growing"],"keywords_am":[]},"va-1.future.s2":{"title_en":"What a virtual assistant does","title_am":null,"anchor":"wwm-s2","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"Virtual assistants handle tasks that keep a business running. Common tasks are managing email inboxes, scheduling meetings in a calendar, entering data into spreadsheets, answering customer messages, booking travel, and preparing simple reports. Some VAs specialise. A social media VA plans and posts content. A bookkeeping VA records invoices and payments. A customer support VA answers questions by chat, email or phone.","keywords_en":["virtual","assistant","tasks","email","customer","assistants","handle","business"],"keywords_am":[]},"va-1.future.s3":{"title_en":"Why demand is growing","title_am":null,"anchor":"wwm-s3","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"Demand for virtual assistants is growing because more companies hire remote workers. Small businesses cannot always afford a full-time office employee, so they hire a VA for a few hours a week. Hiring remotely also lets companies find people in other time zones, so work can continue while the owner sleeps. Reliable internet and cheap video calls have made it possible for a VA in Addis Ababa or Hawassa to work for a client anywhere.","keywords_en":["demand","growing","companies","hire","work","virtual","assistants","because"],"keywords_am":[]},"va-1.future.s4":{"title_en":"Tools for remote work","title_am":null,"anchor":"wwm-s4","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"Most VA work uses a small set of tools: email, a shared calendar, a spreadsheet program, a document editor, a video call app, and a task board where work is tracked. Many clients also use a password manager to share logins safely. You do not need to know every tool. Learn the common ones well and show that you can learn a new tool quickly.","keywords_en":["work","tools","remote","tool","learn","small","set","email"],"keywords_am":[]},"va-1.future.s5":{"title_en":"Skills employers ask for","title_am":null,"anchor":"wwm-s5","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"Employers most often ask for clear written communication, good time management, attention to detail, and reliability. Being able to work without close supervision is important because your client is not in the same room. Soft skills matter as much as tool skills. Telling a client early that a deadline is at risk is a skill.","keywords_en":["skills","employers","ask","client","clear","written","communication","good"],"keywords_am":[]},"va-1.future.s6":{"title_en":"AI and automation","title_am":null,"anchor":"wwm-s6","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"AI tools can now draft emails, summarise documents and sort data. This changes VA work but does not remove it. Clients still need a person who checks the work, makes judgement calls, and keeps track of what matters to the business. VAs who learn to use AI tools carefully can finish routine tasks faster and spend more time on work that needs a person.","keywords_en":["work","automation","tools","person","now","draft","emails","summarise"],"keywords_am":[]},"va-1.future.s7":{"title_en":"Building your portfolio","title_am":null,"anchor":"wwm-s7","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"A portfolio is a small collection of examples that show what you can do. For a VA this can be a sample schedule, a cleaned spreadsheet, a well written email, or a short report. Remove any private client details before you share an example. Keep your portfolio short. Three strong examples are better than ten weak ones.","keywords_en":["portfolio","building","examples","short","small","collection","show","sample"],"keywords_am":[]},"va-1.future.s8":{"title_en":"Key points","title_am":null,"anchor":"wwm-s8","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"The VA industry is growing because companies hire remote workers. Communication, time management and reliability are the skills employers ask for most. AI changes VA work; people who check and decide are still needed. A short portfolio with three examples helps you get your first client.","keywords_en":["key","points","industry","growing","because","companies","hire","remote"],"keywords_am":[]},"va-1.future.s9":{"title_en":"Finishing this lesson","title_am":null,"anchor":"wwm-s9","page_url":"/savanna/pages/concept-with-navigation.html","body_en":"When you have read the lesson, press the Mark as complete button below. Your progress is saved and the next concept opens in the curriculum bar.","keywords_en":["lesson","finishing","have","read","mark","complete","button","progress"],"keywords_am":[]}}};
